    def _serialize(self, obj: typing.Any, *, many: bool = False):
        """Serialize ``obj``.

        :param obj: The object(s) to serialize.
        :param many: `True` if ``obj`` should be serialized as a collection.
        :return: A dictionary of the serialized data
